python3 << 'PYEOF'
import json

# Load definitions from registry
with open('/tmp/receipt_ixp_def.json') as f:
    ixp_def = json.load(f)['Data']['Node']

with open('/tmp/end_def.json') as f:
    end_def = json.load(f)['Data']['Node']

with open('/tmp/script_def.json') as f:
    script_def = json.load(f)['Data']['Node']

# Read existing flow to get id, version, trigger node
with open('/work/output/artifacts/skill-flow-ixp-scaffold-multinode/ReceiptIntake/ReceiptIntake/ReceiptIntake.flow') as f:
    flow = json.load(f)

ixp_type = ixp_def['nodeType']
ixp_version = ixp_def['version']
ixp_defaults = ixp_def.get('inputDefaults', {})
model_blob = ixp_defaults.get('model', {})
# modelName is null, use modelDisplayName
model_name = model_blob.get('modelName') or model_blob.get('modelDisplayName', '')

# Build the new flow
new_flow = {
    "id": flow['id'],
    "version": flow['version'],
    "name": flow['name'],
    "nodes": [
        # Manual trigger (existing)
        flow['nodes'][0],
        # Receipt extractor IxP node
        {
            "id": "extractReceipt",
            "type": ixp_type,
            "typeVersion": ixp_version,
            "display": {"label": "Extract Receipt"},
            "inputs": {
                "model": {
                    "id": model_blob.get("id", ""),
                    "modelName": model_name,
                    "modelDisplayName": model_blob.get("modelDisplayName", model_name),
                    "folderKey": model_blob.get("folderKey", ""),
                    "folderName": model_blob.get("folderName", ""),
                    "folderPath": model_blob.get("folderPath", ""),
                    "description": model_blob.get("description", "")
                },
                "modelName": ixp_defaults.get("modelName") or model_name,
                "projectName": ixp_defaults.get("projectName", ""),
                "folderKey": ixp_defaults.get("folderKey", ""),
                "folderName": ixp_defaults.get("folderName", ""),
                "versionTag": "",
                "pageRange": "",
                "fileRef": "=js:$vars.start.output.receiptFile"
            },
            "outputs": {
                "output": {
                    "name": "output",
                    "type": "object",
                    "source": "=this",
                    "var": "output"
                },
                "error": {
                    "type": "object",
                    "description": "Error information if the node fails",
                    "source": "=Error",
                    "var": "error"
                }
            }
        },
        # Script: postReceipt (wired from success)
        {
            "id": "postReceipt",
            "type": "core.action.script",
            "typeVersion": script_def['version'],
            "display": {"label": "postReceipt"},
            "inputs": {
                "script": "const result = $vars.extractReceipt.output;\nreturn { ok: true, message: 'postReceipt OK', result: result };"
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "The return value of the script",
                    "source": "=result.response",
                    "var": "output"
                }
            }
        },
        # Script: sendToValidation (wired from success)
        {
            "id": "sendToValidation",
            "type": "core.action.script",
            "typeVersion": script_def['version'],
            "display": {"label": "sendToValidation"},
            "inputs": {
                "script": "const result = $vars.extractReceipt.output;\nreturn { ok: true, message: 'sendToValidation OK', result: result };"
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "The return value of the script",
                    "source": "=result.response",
                    "var": "output"
                }
            }
        },
        # Script: logError (wired from error)
        {
            "id": "logError",
            "type": "core.action.script",
            "typeVersion": script_def['version'],
            "display": {"label": "logError"},
            "inputs": {
                "script": "const err = $vars.extractReceipt.error;\nreturn { ok: true, message: 'logError OK', error: err };"
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "The return value of the script",
                    "source": "=result.response",
                    "var": "output"
                }
            }
        },
        # End nodes
        {
            "id": "endSuccess1",
            "type": "core.control.end",
            "typeVersion": end_def['version'],
            "display": {"label": "End"}
        },
        {
            "id": "endSuccess2",
            "type": "core.control.end",
            "typeVersion": end_def['version'],
            "display": {"label": "End"}
        },
        {
            "id": "endError",
            "type": "core.control.end",
            "typeVersion": end_def['version'],
            "display": {"label": "End"}
        }
    ],
    "edges": [
        # trigger -> extractor
        {
            "id": "edge_start_output_extractReceipt_input",
            "sourceNodeId": "start",
            "sourcePort": "output",
            "targetNodeId": "extractReceipt",
            "targetPort": "input"
        },
        # extractor success -> postReceipt
        {
            "id": "edge_extractReceipt_success_postReceipt_input",
            "sourceNodeId": "extractReceipt",
            "sourcePort": "success",
            "targetNodeId": "postReceipt",
            "targetPort": "input"
        },
        # extractor success -> sendToValidation
        {
            "id": "edge_extractReceipt_success_sendToValidation_input",
            "sourceNodeId": "extractReceipt",
            "sourcePort": "success",
            "targetNodeId": "sendToValidation",
            "targetPort": "input"
        },
        # extractor error -> logError
        {
            "id": "edge_extractReceipt_error_logError_input",
            "sourceNodeId": "extractReceipt",
            "sourcePort": "error",
            "targetNodeId": "logError",
            "targetPort": "input"
        },
        # postReceipt -> endSuccess1
        {
            "id": "edge_postReceipt_success_endSuccess1_input",
            "sourceNodeId": "postReceipt",
            "sourcePort": "success",
            "targetNodeId": "endSuccess1",
            "targetPort": "input"
        },
        # sendToValidation -> endSuccess2
        {
            "id": "edge_sendToValidation_success_endSuccess2_input",
            "sourceNodeId": "sendToValidation",
            "sourcePort": "success",
            "targetNodeId": "endSuccess2",
            "targetPort": "input"
        },
        # logError -> endError
        {
            "id": "edge_logError_success_endError_input",
            "sourceNodeId": "logError",
            "sourcePort": "success",
            "targetNodeId": "endError",
            "targetPort": "input"
        }
    ],
    "definitions": [
        flow['definitions'][0],  # core.trigger.manual
        ixp_def,
        script_def,
        end_def
    ],
    "variables": {
        "globals": [
            {
                "id": "receiptFile",
                "direction": "in",
                "type": "file",
                "triggerNodeId": "start"
            }
        ],
        "nodes": []
    },
    "layout": {
        "nodes": {
            "start": flow['layout']['nodes']['start'],
            "extractReceipt": {"position": {"x": 400, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "postReceipt": {"position": {"x": 600, "y": 48}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "sendToValidation": {"position": {"x": 600, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "logError": {"position": {"x": 600, "y": 240}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "endSuccess1": {"position": {"x": 800, "y": 48}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "endSuccess2": {"position": {"x": 800, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
            "endError": {"position": {"x": 800, "y": 240}, "size": {"width": 96, "height": 96}, "collapsed": False}
        }
    }
}

with open('/work/output/artifacts/skill-flow-ixp-scaffold-multinode/ReceiptIntake/ReceiptIntake/ReceiptIntake.flow', 'w') as f:
    json.dump(new_flow, f, indent=2)

print("Flow written OK")
